'use strict';
const $=id=>document.getElementById(id);let chats=[];try{chats=JSON.parse(localStorage.getItem('relay-chats')||'[]');if(!Array.isArray(chats))chats=[]}catch{}let config={url:localStorage.getItem('relay-url')||'',token:''},models=[],active=null,busy=false,connecting=false,controller,installPrompt;
function persist(){try{localStorage.setItem('relay-chats',JSON.stringify(chats))}catch{toast('Storage is full. This conversation could not be saved.')}}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4000)}
function history(){const box=$('history');box.replaceChildren();$('count').textContent=chats.length;for(const c of chats){const row=document.createElement('div');row.className='history-item'+(c.id===active?' selected':'');const b=document.createElement('button');b.textContent='◯  '+c.title;b.onclick=()=>{if(busy)return toast('Stop the current response first.');active=c.id;render();document.body.classList.remove('sidebar-open')};const d=document.createElement('button');d.className='delete';d.textContent='×';d.setAttribute('aria-label','Delete '+c.title);d.onclick=()=>{if(busy)return toast('Stop the current response first.');chats=chats.filter(x=>x.id!==c.id);if(active===c.id)active=null;persist();render()};row.append(b,d);box.append(row)}}
function addMessage(role,content){const box=document.createElement('div');box.className='message '+role;const label=document.createElement('div');label.className='label';label.textContent=role==='user'?'YOU':models.length?'RELAY':'RELAY · DEMO';const text=document.createElement('div');text.textContent=content;box.append(label,text);$('messages').append(box);return text}
function render(){const c=chats.find(c=>c.id===active);$('welcome').hidden=!!c;$('messages').replaceChildren();if(c)for(const m of c.messages)addMessage(m.role,m.content);$('pageTitle').textContent=c?.title||'New conversation';history();scroll()}
function scroll(){$('chat').scrollTop=$('chat').scrollHeight}
function newChat(){if(busy)return toast('Stop the current response first.');active=null;render();$('input').value='';$('input').focus();document.body.classList.remove('sidebar-open')}
function settings(){if(busy)return toast('Stop the current response before changing servers.');$('url').value=config.url;$('token').value=config.token;$('origin').textContent=location.origin;$('settings').showModal();document.body.classList.remove('sidebar-open')}
for(const id of ['settingsButton','serverNav','serverGear','setupHint','connectionShortcut'])$(id).onclick=settings;
$('closeSettings').onclick=()=>$('settings').close();$('new').onclick=newChat;$('chatsNav').onclick=()=>{$('settings').close();document.body.classList.remove('sidebar-open')};$('menu').onclick=()=>document.body.classList.toggle('sidebar-open');$('appearance').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('relay-dark',document.body.classList.contains('dark'))};if(localStorage.getItem('relay-dark')==='true')document.body.classList.add('dark');
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();newChat()}});document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('input').value=b.dataset.prompt;$('input').focus()});
function updateConnection(){const connected=models.length>0;$('status').className=connected?'connected':'';$('status').innerHTML=connected?'<i></i> Ollama connected':'<i></i> Demo mode';$('serverLabel').textContent=connected?'Ollama connected':'Your server, your AI';$('serverSub').textContent=connected?new URL(config.url).host:'Connect Ollama to get started';$('setupHint').hidden=connected;$('privacyNote').textContent=connected?'Chats stay here. Prompts go to your server.':'Conversations stay on this device.';$('model').replaceChildren();for(const m of connected?models:['Demo workspace']){const o=document.createElement('option');o.textContent=m;o.value=connected?m:'';$('model').append(o)}}
function headers(connection=config){return connection.token?{Authorization:'Bearer '+connection.token}:{} }
async function connect(){if(connecting)return;connecting=true;let url=$('url').value.trim().replace(/\/+$/,'');try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error('Enter a base HTTP(S) URL without credentials, query, or fragment.');if(location.protocol==='https:'&&u.protocol!=='https:')throw Error('Use an HTTPS server URL for this hosted app.');const pending={url,token:$('token').value.trim()};$('connect').disabled=true;$('connectionResult').textContent='Connecting to Ollama…';const r=await fetch(url+'/api/tags',{headers:headers(pending),signal:AbortSignal.timeout(15000),cache:'no-store'});if(!r.ok)throw Error('Server returned HTTP '+r.status);const data=await r.json();if(!Array.isArray(data.models))throw Error('This endpoint did not return an Ollama model list.');const nextModels=data.models.map(m=>m.name).filter(n=>typeof n==='string');if(!nextModels.length)throw Error('No models installed. Run ollama pull llama3.2 on the server, then reconnect.');config=pending;models=nextModels;localStorage.setItem('relay-url',url);updateConnection();$('settings').close();toast('Connected. Choose a model and start chatting.')}catch(e){$('connectionResult').textContent=(e.message==='Failed to fetch'?'Could not reach Ollama. Check HTTPS, network access, proxy authentication, and OLLAMA_ORIGINS.':e.message)}finally{connecting=false;$('connect').disabled=false}}
$('settingsForm').onsubmit=e=>{e.preventDefault();connect()};$('demo').onclick=()=>{models=[];updateConnection();$('settings').close();toast('Demo mode enabled. No requests will be sent.')};
async function streamOllama(messages,onText,signal){const r=await fetch(config.url+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json',...headers()},body:JSON.stringify({model:$('model').value,messages,stream:true}),signal});if(!r.ok)throw Error('Ollama returned HTTP '+r.status);if(!r.body)throw Error('Your browser does not support streaming responses.');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',bytes=0;function consume(line){if(!line.trim())return;const event=JSON.parse(line);if(event.error)throw Error(event.error);if(event.message?.content)onText(event.message.content)}while(true){let timeout;const {done,value}=await Promise.race([reader.read(),new Promise((_,reject)=>{timeout=setTimeout(()=>{controller.abort();reject(Error('Server response timed out.'))},60000)})]).finally(()=>clearTimeout(timeout));if(done)break;bytes+=value.byteLength;if(bytes>4*1024*1024){controller.abort();throw Error('Response exceeded the 4 MB limit.')}buffer+=decoder.decode(value,{stream:true});if(buffer.length>1024*1024){controller.abort();throw Error('Server sent an oversized streaming record.')}let end;while((end=buffer.indexOf('\n'))>=0){consume(buffer.slice(0,end));buffer=buffer.slice(end+1)}}buffer+=decoder.decode();consume(buffer)}
$('composer').onsubmit=async e=>{e.preventDefault();if(busy){controller.abort();return}if(connecting)return toast('Wait for the server connection check to finish.');const text=$('input').value.trim();if(!text)return;let c=chats.find(c=>c.id===active);if(!c){c={id:crypto.randomUUID(),title:text.slice(0,45),messages:[]};chats.unshift(c);active=c.id}c.messages.push({role:'user',content:text});$('input').value='';$('input').style.height='';persist();render();busy=true;controller=new AbortController();$('send').textContent='■';$('send').setAttribute('aria-label','Stop response');$('model').disabled=true;const reply={role:'assistant',content:''},node=addMessage('assistant','Thinking…');let received=false;try{if(models.length){await streamOllama(c.messages,part=>{if(!received){received=true;node.textContent=''}reply.content+=part;node.textContent=reply.content;scroll()},controller.signal);if(!reply.content)throw Error('Ollama returned an empty response.')}else{reply.content='This is your Relay demo workspace. Once you connect Ollama, your model’s replies will stream here.\n\nOpen Server connection, enter your HTTPS Ollama URL, and select a model. Your chats will stay on this device, and prompts will go directly to your server.\n\nYour message has been saved so you can return to it later.';node.textContent=reply.content}c.messages.push(reply)}catch(err){if(reply.content)c.messages.push(reply);if(err.name==='AbortError'){if(!reply.content)node.textContent='Response stopped.'}else{node.classList.add('error');node.textContent='Connection interrupted: '+err.message+'\nCheck your server settings and try again.'}}finally{busy=false;persist();$('send').textContent='↑';$('send').setAttribute('aria-label','Send message');$('model').disabled=false;history();scroll()}};
$('input').oninput=()=>{$('input').style.height='auto';$('input').style.height=Math.min($('input').scrollHeight,180)+'px'};$('input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('composer').requestSubmit()}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true}};if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline support could not be enabled.'));
render();updateConnection();
